// Lab workbench helper: stage counts for the Lab load tiles and the Certificate watch rows.
// Runs on records.onDataQuerySuccess and Lab workbench onPageLoad.
const rows = queries.records.data || [];
const active = rows.filter(r => !['Completed', 'Cancelled'].includes(r.status));
const count = s => active.filter(r => r.status === s).length;
const d = s => /^\d{4}-\d{2}-\d{2}$/.test(s || '') ? new Date(s + 'T12:00:00Z').toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : 'Unscheduled';
const watch = active.slice(0, 3); // owner's decision: same order as today (first three active jobs)
return {
  draft: count('Draft'),
  scheduled: count('Scheduled'),
  inProgress: count('In progress'),
  ready: count('Ready'),
  watch: watch.map(r => ({ id: r.id, name: r.name, owner: r.owner, due: d(r.due) }))
};

// Instrument record helper: the selected job's summary card fields and its activity history.
// Runs on records.onDataQuerySuccess and Instrument record onPageLoad.
const e = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[c]));
const p = (queries.records.data || []).find(r => r.id === variables.recordId);
const money = n => Number(n || 0).toLocaleString('en-US', { style: 'currency', currency: 'USD' });
const date = s => /^\d{4}-\d{2}-\d{2}$/.test(s || '') ? new Date(s + 'T12:00:00Z').toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) : 'Not scheduled';
const time = n => String(Math.floor(n)).padStart(2, '0') + ':' + String(Math.round((n % 1) * 60)).padStart(2, '0');
const items = (p && p.items) || [], decisions = (p && p.decisions) || [];
const total = Math.round(items.reduce((n, i) => n + Number(i.quantity || 0) * Number(i.rate || 0), 0) * 100) / 100;
const paid = Math.round(decisions.filter(d => d.type === 'payment').reduce((n, d) => n + Number(d.amount || 0), 0) * 100) / 100;
const b = decisions.filter(d => d.type === 'booking').slice(-1)[0];
const history = ((p && p.history) || []).slice().reverse().map(h => ({
  lineHtml: '<b>' + e(h.event) + '</b> <span style="color:var(--cc-placeholder-text);">' + e(String(h.at || '').slice(0, 16).replace('T', ' ')) + '</span>',
  note: h.note || ''
}));
return {
  has: !!p,
  context: (p && p.context) || '',
  scope: (p && p.scope) || '',
  owner: (p && p.owner) || '',
  bookingLine: b ? date(b.date) + ' · ' + time(b.start) + '–' + time(b.start + b.duration) : '',
  statusTag: [{ title: (p && p.status) || 'Not selected', color: 'var(--cc-surface2-surface)', textColor: 'var(--cc-primary-brand)' }],
  total: money(total),
  remaining: money(total - paid) + ' remaining',
  history: history.length ? history : [{ lineHtml: '', note: 'Select a record to inspect its saved activity.' }]
};
